$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$d=Join-Path $env:USERPROFILE 'asd-diagnostics-20261128';$p=Join-Path ([Environment]::GetFolderPath('Desktop')) 'Agent Session Desk Alpha 8234c4e';$hashes=Get-Content -Raw (Join-Path $d 'native-hashes.json')|ConvertFrom-Json;foreach($f in $hashes.PSObject.Properties){if((Get-FileHash (Join-Path $d $f.Name)).Hash.ToLowerInvariant()-cne $f.Value){throw 'Test image changed'}};$env:ASD_NATIVE_MESSAGING_BUNDLE=Join-Path $p 'terminal-runtime';$env:ASD_NATIVE_MESSAGING_FIXTURE=Join-Path $d 'asd-fixture.exe';if((Get-FileHash (Join-Path $env:ASD_NATIVE_MESSAGING_BUNDLE 'psmux.exe')).Hash.ToLowerInvariant()-cne 'ff9d8893ecc53ac5caca3bae0146d75ebcaf2cf7edc4abf9d87578469fb7b16b'){throw 'Backend changed'};$results=@();foreach($name in @('diagnostics','ui')){$pattern='.';if($name-eq 'ui'){$pattern='Test(Diagnostics|DiagnosticExport|WindowsNativeDiagnostics)'};$child=Start-Process -FilePath (Join-Path $d ($name+'.test.exe')) -ArgumentList '-test.run',$pattern,'-test.v','-test.timeout','120s' -NoNewWindow -PassThru -Wait -RedirectStandardOutput (Join-Path $d ($name+'.log')) -RedirectStandardError (Join-Path $d ($name+'-stderr.log'));$results+=@{package=$name;exit_code=$child.ExitCode}};$results|ConvertTo-Json|Set-Content (Join-Path $d 'results.json');$results|ConvertTo-Json